#include <iostream>
#include <string>
#include <fstream>
#include <unordered_map>
#include <limits>

using namespace std;

bool isValidFilename(const string& filename) {
    // Simple validation: check for invalid characters
    for (char c : filename) {
        if (c == '/' || c == '\\' || c == '.' || c == '..') {
            return false;
        }
    }
    return true;
}

int main() {
    // Variable declarations
    int cases = 0, partyAmount = 0, voteAmount = 0;
    string filename, party, candidate, vote, winner;
    int maxVotes = 0;
    bool tie = false;

    // File handling
    cout << "Enter filename: ";
    getline(cin, filename);

    if (!isValidFilename(filename)) {
        cerr << "Invalid filename. Please enter a valid filename." << endl;
        return 1;
    }

    ifstream infile(filename);
    if (!infile.is_open()) {
        cerr << "Error opening file. Please check the filename and try again." << endl;
        return 1;
    }

    if (!(infile >> cases)) {
        cerr << "Error reading the number of cases from the file." << endl;
        infile.close();
        return 1;
    }

    infile.ignore(numeric_limits<streamsize>::max(), '\n'); // Ignore the rest of the line

    for (int i = 0; i < cases; i++) {
        // Reset variables for each case
        unordered_map<string, int> votes;
        unordered_map<string, string> parties;
        tie = false;

        // Read party information
        if (!(infile >> partyAmount)) {
            cerr << "Error reading the number of parties for case " << i + 1 << "." << endl;
            infile.close();
            return 1;
        }
        infile.ignore(numeric_limits<streamsize>::max(), '\n'); // Ignore the rest of the line

        for (int j = 0; j < partyAmount; j++) {
            if (!getline(infile, candidate) || !getline(infile, party)) {
                cerr << "Error reading party information for case " << i + 1 << "." << endl;
                infile.close();
                return 1;
            }
            parties[candidate] = party;
        }

        // Read vote information
        if (!(infile >> voteAmount)) {
            cerr << "Error reading the number of votes for case " << i + 1 << "." << endl;
            infile.close();
            return 1;
        }
        infile.ignore(numeric_limits<streamsize>::max(), '\n'); // Ignore the rest of the line

        for (int j = 0; j < voteAmount; j++) {
            if (!getline(infile, vote)) {
                cerr << "Error reading vote information for case " << i + 1 << "." << endl;
                infile.close();
                return 1;
            }
            votes[vote]++;
        }

        // Find the winner or check for a tie
        for (auto& [candidate, voteCount] : votes) {
            if (voteCount > maxVotes) {
                winner = parties[candidate];
                maxVotes = voteCount;
                tie = false;
            } else if (voteCount == maxVotes) {
                tie = true;
            }
        }

        // Display results
        if (tie) {
            cout << "Case " << i + 1 << " results: Tie" << endl;
        } else {
            cout << "Case " << i + 1 << " results: " << winner << endl;
        }
    }

    infile.close();
    return 0;
}
